const query = $input.first().json.query || {};
const fileId = query.file_id || '';
const code = query.code || '';

if (!fileId || !code) {
  return [{ json: { valid: false, error: 'Parametres manquants (file_id ou code)' } }];
}

return [{ json: { valid: true, file_id: fileId, code: code } }];

const query = $('Extraire parametres').first().json;
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const flashcards = JSON.parse(buffer.toString('utf-8'));

if (flashcards.code_suppression !== query.code) {
  return [{ json: { verified: false, error: 'Code de validation invalide' } }];
}

// T-SEC (2026-10-06) - TEST : meme logique que la version prod, voir ce fichier.
if (flashcards.type === 'fonda' && flashcards.revue_carte_par_carte !== true) {
  return [{ json: {
    verified: false,
    error: 'Ce jeu Box-FONDA doit etre relu carte par carte via le lien de selection recu par email, pas valide en bloc depuis cet ancien lien.',
  } }];
}

return [{ json: {
  verified: true,
  id: flashcards.id,
  matiere: flashcards.matiere,
  niveau: flashcards.niveau,
  notion: flashcards.notion,
  prof_nom: flashcards.prof_nom,
  prof_email: flashcards.prof_email,
  nb_cartes: flashcards.nb_cartes || flashcards.cartes.length,
  date_creation: flashcards.date_creation,
  drive_file_id: query.file_id
} }];

const setData = $('Verifier code').first().json;

let catalogue;
try {
  const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
  let parsed = JSON.parse(buffer.toString('utf-8'));
  if (typeof parsed === 'string') parsed = JSON.parse(parsed);
  if (typeof parsed === 'object' && Array.isArray(parsed.sets)) {
    catalogue = parsed;
  } else {
    catalogue = { last_updated: '', total_sets: 0, sets: [] };
  }
} catch (e) {
  catalogue = { last_updated: '', total_sets: 0, sets: [] };
}

if (catalogue.sets.some(s => s.id === setData.id)) {
  return [{ json: { already_published: true, notion: setData.notion } }];
}

catalogue.sets.push({
  id: setData.id,
  matiere: setData.matiere,
  niveau: setData.niveau,
  notion: setData.notion,
  prof_nom: setData.prof_nom,
  nb_cartes: setData.nb_cartes,
  date_creation: setData.date_creation,
  drive_file_id: setData.drive_file_id
});

catalogue.total_sets = catalogue.sets.length;
catalogue.last_updated = new Date().toISOString();

return [{ json: {
  catalogue_json: JSON.stringify(catalogue, null, 2),
  notion: setData.notion,
  already_published: false
} }];

